pub fn rotate(a: Vec<i32>, offset: usize) -> Vec<i32> {
    let n = a.len();
    if n == 0 {
        // Empty input yields empty output.
        return Vec::new();
    }

    // Compute effective rotation within bounds [0, n).
    let o = offset % n;

    // Build the rotated vector by taking the slice from o..n
    // and then 0..o.
    let mut b = Vec::with_capacity(n);
    b.extend_from_slice(&a[o..]);
    b.extend_from_slice(&a[..o]);
    b
}

